import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"账号与安全","description":"","frontmatter":{},"headers":[],"relativePath":"guide/account-security.md","filePath":"guide/account-security.md","lastUpdated":1788621106000}`),a={name:`guide/account-security.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="账号与安全" tabindex="-1">账号与安全 <a class="header-anchor" href="#账号与安全" aria-label="Permalink to “账号与安全”">​</a></h1><h2 id="登录方式" tabindex="-1">登录方式 <a class="header-anchor" href="#登录方式" aria-label="Permalink to “登录方式”">​</a></h2><p>草丛 Mail 支持本地账号和管理员已启用的 OAuth 登录。当前站点入口为 <a href="https://to9.us/app/" target="_blank" rel="noreferrer">https://to9.us/app/</a>，旧登录地址会自动转到新入口。</p><p>本地账号使用用户名和密码登录。注册、邮箱验证码、找回密码和绑定邮箱是否开放，以平台当时的后台设置为准。OAuth 按钮也只会显示已启用的提供方。</p><h2 id="密码与会话" tabindex="-1">密码与会话 <a class="header-anchor" href="#密码与会话" aria-label="Permalink to “密码与会话”">​</a></h2><p>密码应只用于网页登录。邮件客户端请使用对应邮箱生成的应用专用密码。修改账号密码、完成密码找回、由管理员重置密码或重置 2FA 后，系统会撤销原有登录令牌；请在可信设备上重新登录。</p><p>忘记密码时，从登录页进入找回流程。账号必须已绑定可接收验证码的邮箱；若没有可用的绑定邮箱，请通过工单联系管理员核验身份。</p><p>找回邮箱不能在普通资料保存接口中直接改写，必须通过邮箱验证码绑定流程证明地址所有权。</p><h2 id="两步验证" tabindex="-1">两步验证 <a class="header-anchor" href="#两步验证" aria-label="Permalink to “两步验证”">​</a></h2><p>在账号安全设置中启用 TOTP 两步验证：</p><ol><li>用身份验证器扫描二维码或录入密钥。</li><li>输入当前六位验证码完成确认。</li><li>保存恢复信息，并退出后验证一次登录流程。</li></ol><p>更换手机前先迁移身份验证器。若设备丢失且无法验证，只能联系管理员在核验身份后重置 2FA。</p><h2 id="oauth-绑定" tabindex="-1">OAuth 绑定 <a class="header-anchor" href="#oauth-绑定" aria-label="Permalink to “OAuth 绑定”">​</a></h2><p>已登录用户可以绑定管理员开放的 OAuth 账号。解绑前应确认本地密码或另一种登录方式可用，避免失去账号访问权。</p><h2 id="安全记录" tabindex="-1">安全记录 <a class="header-anchor" href="#安全记录" aria-label="Permalink to “安全记录”">​</a></h2><p>安全记录包含登录来源、时间和关键账号操作。发现陌生记录时，依次修改密码、强制退出其他会话、撤销邮箱应用专用密码，并检查 OAuth 绑定。</p><h2 id="凭据保护" tabindex="-1">凭据保护 <a class="header-anchor" href="#凭据保护" aria-label="Permalink to “凭据保护”">​</a></h2><ul><li>不要在聊天、工单或截图中展示密码、TOTP 密钥、应用专用密码和 API 密钥。</li><li>API 密钥只在创建时完整显示，应立即保存在密码管理器中。</li><li>公共设备使用完毕后退出账号，不要让浏览器保存凭据。</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};